/**
 * The egg catalogue, generated by scripts/sync-eggs.mjs from the daily
 * pelican-eggs index and Pelican Hub. Run `pnpm sync:eggs` to refresh it;
 * `pnpm build` tries to refresh it too and falls back to the saved file when offline.
 *
 * This module imports the whole catalogue, so client components should import
 * from lib/egg-helpers.ts instead (types and helpers, no data).
 */
import data from '@/data/eggs.json';
import type { EggGame } from './egg-helpers';

export * from './egg-helpers';

export interface EggIndex {
  generatedAt: string;
  source: string;
  /** When Pelican Hub was last reached; null if it never was. */
  hubFetchedAt: string | null;
  categories: { id: string; name: string; count: number }[];
  games: EggGame[];
}

export const eggIndex = data as EggIndex;

export const eggCount = eggIndex.games.reduce((n, g) => n + g.eggs.length, 0);
export const gameCount = eggIndex.games.filter((g) => g.category === 'games' || g.category === 'minecraft').length;

/** Games shown as tiles on the homepage (scripts/sync-eggs.mjs reads this list to save their icons). */
export const FEATURED = ['minecraft', 'rust', 'palworld', 'valheim', 'factorio', 'counter-strike-2'];

export function gameBySlug(slug: string): EggGame | undefined {
  return eggIndex.games.find((g) => g.slug === slug);
}
